```cpp
#include <iostream>
#include <vector>
#include <list>

int main() {
    // vector 常用操作
    std::vector<int> nums;
    nums.reserve(100);  // 预分配，避免多次重新分配

    for (int i = 0; i < 10; ++i) {
        nums.push_back(i);
    }

    // 范围 for 遍历
    for (const auto& n : nums) {
        std::cout << n << " ";
    }
    std::cout << std::endl;

    // 删除偶数（注意迭代器失效问题）
    for (auto it = nums.begin(); it != nums.end(); ) {
        if (*it % 2 == 0) {
            it = nums.erase(it);  // erase 返回下一个有效迭代器
        } else {
            ++it;
        }
    }

    // 列表 splice 示例
    std::list<int> list1 = {1, 2, 3};
    std::list<int> list2 = {4, 5, 6};
    auto it = list1.begin();
    ++it;  // 指向 2
    list1.splice(it, list2);  // 将 list2 全部插入到 2 之前
    // list1: 1, 4, 5, 6, 2, 3
    // list2: 空

    return 0;
}
