### 2. 类模板
```cpp
template <typename T>
class Stack {
public:
    void push(const T& value) {
        data.push_back(value);
    }

    void pop() {
        if (!data.empty()) data.pop_back();
    }

    T& top() {
        return data.back();
    }

    bool empty() const {
        return data.empty();
    }

private:
    std::vector<T> data;
};

// 使用
