### 3. 模板特化
```cpp
// 通用版本
template <typename T>
class Comparator {
public:
    bool equal(T a, T b) {
        return a == b;
    }
};

// 全特化：针对 const char*
template <>
class Comparator<const char*> {
public:
    bool equal(const char* a, const char* b) {
        return strcmp(a, b) == 0;
    }
};

// 偏特化：针对指针类型
template <typename T>
class Comparator<T*> {
public:
    bool equal(T* a, T* b) {
        return *a == *b;  // 比较指向的内容
    }
};
```

### 4. 变参模板（C++11）
```cpp
// 递归终止
template <typename T>
T sum(T value) {
    return value;
}

// 变参展开
template <typename T, typename... Args>
T sum(T first, Args... args) {
    return first + sum(args...);
}

// 使用
int result = sum(1, 2, 3, 4, 5);  // 15

// C++17 折叠表达式
template <typename... Args>
auto sum_fold(Args... args) {
    return (args + ...);  // 一元右折叠
}
```

### 5. 类型特征（C++11）
```cpp
#include <type_traits>

// 编译期类型判断
std::is_integral<int>::value;        // true
std::is_pointer<int*>::value;        // true
std::is_reference<int&>::value;      // true

// enable_if：条件模板启用
template <typename T>
typename std::enable_if<std::is_integral<T>::value, T>::type
foo(T value) {
    return value * 2;
}

// C++14 简化
std::is_integral_v<int>;  // 等价于 std::is_integral<int>::value
```

### 6. 概念（Concepts，C++20）
```cpp
template <typename T>
concept Addable = requires(T a, T b) {
    { a + b } -> std::convertible_to<T>;
};

template <Addable T>
T add(T a, T b) {
    return a + b;
}
```

