class Calculator {
public:
    double evaluate(const std::string& expression) {
        auto tokens = tokenize(expression);
        auto postfix = infixToPostfix(tokens);
        return evaluatePostfix(postfix);
    }

private:
    enum class TokenType { Number, Operator, LeftParen, RightParen };

    struct Token {
        TokenType type;
        double value;      // 对于数字
        char op;           // 对于运算符
