        switch (op) {
            case '+': case '-': return 1;
            case '*': case '/': return 2;
            default: return 0;
        }
    }

    std::vector<Token> infixToPostfix(const std::vector<Token>& tokens) {
        std::vector<Token> output;
        std::stack<Token> opStack;
        // 实现 Shunting Yard 算法...
